use crate::color::types::{CMYK, HSL, HSV, RGB, YUV};

pub struct ColorConverter;

impl ColorConverter {
    pub fn rgb_to_hsl(rgb: RGB) -> HSL {
        let max = max3(rgb.r, rgb.g, rgb.b);
        let min = min3(rgb.r, rgb.g, rgb.b);
        let l = (max + min) / 2.0_f32;
        let delta = max - min;

        if delta == 0.0_f32 {
            return HSL {
                h: 0.0_f32,
                s: 0.0_f32,
                l,
            };
        }

        let s = if l > 0.5_f32 {
            delta / (2.0_f32 - max - min)
        } else {
            delta / (max + min)
        };

        HSL {
            h: hue(rgb, max, delta),
            s,
            l,
        }
    }

    pub fn rgb_to_hsv(rgb: RGB) -> HSV {
        let max = max3(rgb.r, rgb.g, rgb.b);
        let min = min3(rgb.r, rgb.g, rgb.b);
        let v = max;
        let delta = max - min;

        if delta == 0.0_f32 {
            return HSV {
                h: 0.0_f32,
                s: 0.0_f32,
                v,
            };
        }

        HSV {
            h: hue(rgb, max, delta),
            s: delta / max,
            v,
        }
    }

    pub fn rgb_to_cmyk(rgb: RGB) -> CMYK {
        let max = max3(rgb.r, rgb.g, rgb.b);
        let k = 1.0_f32 - max;

        if k == 1.0_f32 {
            return CMYK {
                c: 0.0_f32,
                m: 0.0_f32,
                y: 0.0_f32,
                k,
            };
        }

        let denominator = 1.0_f32 - k;

        CMYK {
            c: (1.0_f32 - rgb.r - k) / denominator,
            m: (1.0_f32 - rgb.g - k) / denominator,
            y: (1.0_f32 - rgb.b - k) / denominator,
            k,
        }
    }

    pub fn rgb_to_yuv(rgb: RGB) -> YUV {
        YUV {
            y: 0.299_f32 * rgb.r + 0.587_f32 * rgb.g + 0.114_f32 * rgb.b,
            u: -0.147_f32 * rgb.r - 0.289_f32 * rgb.g + 0.436_f32 * rgb.b,
            v: 0.615_f32 * rgb.r - 0.515_f32 * rgb.g - 0.100_f32 * rgb.b,
        }
    }
}

fn hue(rgb: RGB, max: f32, delta: f32) -> f32 {
    let mut h = if max == rgb.r {
        (rgb.g - rgb.b) / delta
    } else if max == rgb.g {
        (rgb.b - rgb.r) / delta + 2.0_f32
    } else {
        (rgb.r - rgb.g) / delta + 4.0_f32
    } * 60.0_f32;

    if h < 0.0_f32 {
        h += 360.0_f32;
    }

    h
}

fn max3(a: f32, b: f32, c: f32) -> f32 {
    max_left(max_left(a, b), c)
}

fn min3(a: f32, b: f32, c: f32) -> f32 {
    min_left(min_left(a, b), c)
}

fn max_left(a: f32, b: f32) -> f32 {
    if b > a { b } else { a }
}

fn min_left(a: f32, b: f32) -> f32 {
    if b < a { b } else { a }
}

