#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum ParseErrorKind {
    Invalid,
    OutOfRange,
}

pub fn parse_stof_like(input: &str) -> Result<f32, ParseErrorKind> {
    let trimmed = input.trim_start();
    if trimmed.is_empty() {
        return Err(ParseErrorKind::Invalid);
    }

    let sign_len = match trimmed.as_bytes()[0] {
        b'+' | b'-' => 1,
        _ => 0,
    };
    let sign = &trimmed[..sign_len];
    let rest = &trimmed[sign_len..];

    if let Some(parsed) = parse_special(sign, rest) {
        return Ok(parsed);
    }

    let prefix_len = scan_decimal_prefix(trimmed).ok_or(ParseErrorKind::Invalid)?;
    let prefix = &trimmed[..prefix_len];
    let parsed = prefix.parse::<f64>().map_err(|_| ParseErrorKind::OutOfRange)?;

    if parsed.is_finite() && parsed != 0.0 {
        let abs = parsed.abs();
        if abs < f32::MIN_POSITIVE as f64 || abs > f32::MAX as f64 {
            return Err(ParseErrorKind::OutOfRange);
        }
    }

    Ok(parsed as f32)
}

fn parse_special(sign: &str, rest: &str) -> Option<f32> {
    let lower = rest.to_ascii_lowercase();

    if lower.starts_with("infinity") || lower.starts_with("inf") {
        return Some(if sign == "-" {
            f32::NEG_INFINITY
        } else {
            f32::INFINITY
        });
    }

    if lower.starts_with("nan") {
        return Some(if sign == "-" { -f32::NAN } else { f32::NAN });
    }

    None
}

fn scan_decimal_prefix(input: &str) -> Option<usize> {
    let bytes = input.as_bytes();
    let mut index = 0;

    if matches!(bytes[index], b'+' | b'-') {
        index += 1;
        if index == bytes.len() {
            return None;
        }
    }

    let integer_start = index;
    while index < bytes.len() && bytes[index].is_ascii_digit() {
        index += 1;
    }
    let mut saw_digit = index > integer_start;

    if index < bytes.len() && bytes[index] == b'.' {
        index += 1;
        let fraction_start = index;
        while index < bytes.len() && bytes[index].is_ascii_digit() {
            index += 1;
        }
        saw_digit |= index > fraction_start;
    }

    if !saw_digit {
        return None;
    }

    if index < bytes.len() && matches!(bytes[index], b'e' | b'E') {
        let exponent_mark = index;
        let mut exponent_index = index + 1;
        if exponent_index < bytes.len() && matches!(bytes[exponent_index], b'+' | b'-') {
            exponent_index += 1;
        }

        let exponent_digits_start = exponent_index;
        while exponent_index < bytes.len() && bytes[exponent_index].is_ascii_digit() {
            exponent_index += 1;
        }

        if exponent_index > exponent_digits_start {
            index = exponent_index;
        } else {
            index = exponent_mark;
        }
    }

    Some(index)
}

